-- Görev kataloğu sürüm 2 temizliği (öneri, 23 Ekim 2026; kullanıcı: kaynak uygulamanın adları hiçbir uygulamada ve platformda görünmesin).
-- 1) İngilizce kaynak adı sütunu kalkar. 2) Şablonlar yeni anahtarlarla (gs_<kategori>_<sıra>) yazılır.
-- 3) Kayıtlı şablonlar ve uzman önerilerindeki eski anahtar, aynı başlıklı yeni şablonun anahtarına çevrilir. 4) Eski anahtarlı satırlar silinir.
-- Tekrar çalıştırılabilir; temiz kurulumda 2–4 boşa çalışır.
alter table public.task_templates drop column if exists source_en;

-- Süzgeç: kategori (etiketlerde) + yaş grubu (boş = hepsi). Oturum gerekir.
create or replace function public.task_templates_for(p_category text default null, p_band text default null)
returns setof public.task_templates language sql stable security invoker set search_path = public as $$
  select * from public.task_templates t
   where t.active
     and (p_category is null or p_category = any(t.categories))
     and (p_band is null or p_band = any(t.age_bands))
   order by t.sort
$$;
revoke execute on function public.task_templates_for(text, text) from public, anon;
grant execute on function public.task_templates_for(text, text) to authenticated;

on conflict (key) do update set title = excluded.title, emoji = excluded.emoji, category = excluded.category,
  categories = excluded.categories, age_bands = excluded.age_bands, difficulty = excluded.difficulty, coins = excluded.coins,
  skill = excluded.skill, sort = excluded.sort;

-- eski anahtar → yeni anahtar (başlıklar tekil)
update public.saved_templates s set template_key = n.key
  from public.task_templates o join public.task_templates n on n.title = o.title and n.key like 'gs\_%'
 where o.key like 'jt\_%' and s.template_key = o.key
   and not exists (select 1 from public.saved_templates x where x.family_id = s.family_id and x.template_key = n.key);
delete from public.saved_templates s using public.task_templates o where o.key like 'jt\_%' and s.template_key = o.key;   -- aynı aile yeni anahtarı zaten kaydetmişse eski kopya
update public.clinic_task_suggestions s set template_key = n.key
  from public.task_templates o join public.task_templates n on n.title = o.title and n.key like 'gs\_%'
 where o.key like 'jt\_%' and s.template_key = o.key;
delete from public.task_templates where key like 'jt\_%';
